window.__WB_TEXTBOOK__ = [{"id": "rosen-qu-dm-fusion", "name": "《离散数学及其应用》×《离散数学》融合精讲", "author": "Kenneth H. Rosen / 屈婉玲", "level": "计算机科学核心必修 / 考研与竞赛基础", "chapters": [{"cid": "dm-ch01", "title": "第1章 命题逻辑、范式与推理演算（Propositional Logic & Normal Forms）", "summary": "本章融合 Rosen 的逻辑演算体系与屈婉玲的代数化范式理论。命题公式由原子命题与联结词 $\\{\\neg, \\land, \\lor, \\to, \\leftrightarrow\\}$ 递归构成，其中 $\\{\\neg, \\land\\}$、$\\{\\uparrow\\}$（与非）及 $\\{\\downarrow\\}$（或非）均为极小联结词完备集。通过基本等值式（德摩根律、蕴涵等值式 $p\\to q \\Leftrightarrow \\neg p \\lor q$、吸收律）可将任意公式化为唯一的标准形式——主析取范式（PDNF，由极小项 $m_i$ 析取构成）与主合取范式（PCNF，由极大项 $M_j$ 合取构成），两者成真赋值集合互补，直接决定公式的可满足性与重言性。在形式推理层面，自然推理系统结合假言推理（MP）、拒取式（MT）、附加前提法（CP 规则）及归谬法（反证法），并与面向自动定理证明的归结原理（Resolution）形成理论闭环。", "template_cpp": "// 极小项编码与主析取/主合取范式求值骨架 (n<=20)\n#include <bits/stdc++.h>\nusing namespace std;\nvoid print_normal_forms(int n, const function<bool(int)>& eval) {\n    vector<int> minterms, maxterms;\n    for (int mask = 0; mask < (1 << n); ++mask) {\n        if (eval(mask)) minterms.push_back(mask);\n        else maxterms.push_back(mask);\n    }\n    // PDNF = bigvee_{i in minterms} m_i; PCNF = bigwedge_{j in maxterms} M_j\n}", "pitfalls": "1. 主析取范式极小项 $m_i$ 编码规则中，$1$ 对应正文字 $p$、$0$ 对应负文字 $\\neg p$，而主合取范式极大项 $M_j$ 恰好相反（$0$ 对应 $p$、$1$ 对应 $\\neg p$）；2. 使用条件证明（CP 规则）引入附加前提时，若在归谬子推导中混用外层未撤销的假设导致推理失效；3. 消解（归结）时一次消去两对互补文字，错误地将 $(p\\lor q)$ 与 $(\\neg p\\lor \\neg q)$ 直接消解为空子句。", "workbench_tags": ["主析取范式", "主合取范式", "自然推理CP规则", "归结原理", "联结词完备集"], "problems": [{"oj": "教材精选题", "pid": "DM-01-01", "title": "等值演算化简并求主析取范式与主合取范式", "diff": "基础", "hint": "破题思路：先消去条件与双条件联结词，再用德摩根律和分配律展开为极小项析取，最后由补集写出主合取范式。\n解答要点：\n1. 求公式 $A = (p \\to q) \\land (\\neg q \\to r)$ 在命题变元 $p, q, r$ 下的主范式。\n2. 消去蕴涵：$A \\Leftrightarrow (\\neg p \\lor q) \\land (q \\lor r) \\Leftrightarrow q \\lor (\\neg p \\land r)$（逆用分配律）。\n3. 补全变元展开为极小项：$q \\Leftrightarrow (p\\lor \\neg p)\\land q\\land (r\\lor \\neg r) = m_2 \\lor m_3 \\lor m_6 \\lor m_7$；$\\neg p \\land r \\Leftrightarrow \\neg p \\land (q\\lor \\neg q) \\land r = m_1 \\lor m_3$。\n4. 合并去重得主析取范式：$A \\Leftrightarrow m_1 \\lor m_2 \\lor m_3 \\lor m_6 \\lor m_7$（即 $\\sum(1,2,3,6,7)$）。\n5. 取全集 $\\{0,\\dots,7\\}$ 的补集得主合取范式：$A \\Leftrightarrow M_0 \\land M_4 \\land M_5$（即 $\\prod(0,4,5)$）。"}, {"oj": "教材精选题", "pid": "DM-01-02", "title": "自然推理系统中使用附加前提（CP 规则）证明蕴涵式", "diff": "中档", "hint": "破题思路：当结论形如 $A \\to B$ 时，将 $A$ 放入前提集合作为附加前提，只需推出 $B$ 即可。\n解答要点：\n1. 前提：$p \\to (q \\to r)$，$\\neg s \\lor p$，$q$；结论：$s \\to r$。\n2. 引入附加前提：$s$（CP 规则）。\n3. 由 $s$ 与 $\\neg s \\lor p$（析取三段论）推出 $p$。\n4. 由 $p$ 与 $p \\to (q \\to r)$（假言推理 MP）推出 $q \\to r$。\n5. 由前提 $q$ 与 $q \\to r$（假言推理 MP）推出 $r$。\n6. 撤销附加前提 $s$，由 CP 规则得证 $s \\to r$。"}, {"oj": "教材精选题", "pid": "DM-01-03", "title": "归结反演（Resolution）证明推理有效性", "diff": "中档", "hint": "破题思路：将所有前提及结论的否定转化为合取范式子句集 $S$，反复应用归结规则直到推出空子句 $\\square$。\n解答要点：\n1. 验证推理：前提 $(p\\lor q) \\to r$，$r \\to s$，$p$；结论 $s$。\n2. 化前提与结论否定 $\\neg s$ 为子句集：\n   $C_1: \\neg p \\lor r$，$C_2: \\neg q \\lor r$（由 $(p\\lor q)\\to r \\Leftrightarrow (\\neg p\\land \\neg q)\\lor r$ 分配得），$C_3: \\neg r \\lor s$，$C_4: p$，$C_5: \\neg s$。\n3. 归结步骤：$C_1$ 与 $C_4$ 消去 $p$ 得 $C_6: r$；$C_6$ 与 $C_3$ 消去 $r$ 得 $C_7: s$；$C_7$ 与 $C_5$ 消去 $s$ 得空子句 $\\square$，证毕。"}, {"oj": "教材精选题", "pid": "DM-01-04", "title": "证明联结词集合的极小完备性", "diff": "压轴", "hint": "破题思路：要证 $S$ 为完备集，只需用 $S$ 中的联结词表达出已知完备集 $\\{\\neg, \\land\\}$ 或 $\\{\\neg, \\lor\\}$；要证极小性，需验证去掉任一元素后不再完备（如保真/保假性封闭）。\n解答要点：\n1. 证明 $\\{\\uparrow\\}$（与非，$p\\uparrow q \\Leftrightarrow \\neg(p\\land q)$）为完备集：\n   - 表达否定：$\\neg p \\Leftrightarrow p \\uparrow p$。\n   - 表达合取：$p \\land q \\Leftrightarrow \\neg(p\\uparrow q) \\Leftrightarrow (p\\uparrow q) \\uparrow (p\\uparrow q)$。\n2. 因 $\\{\\neg, \\land\\}$ 完备且 $\\{\\uparrow\\}$ 仅含一个联结词，故其必为极小完备集。\n3. 同理可证 $\\{\\to, \\bot\\}$（蕴涵与假常元）也是极小完备集：$\\neg p \\Leftrightarrow p\\to\\bot$，$p\\lor q \\Leftrightarrow \\neg p \\to q$；若去掉 $\\bot$，则仅用 $\\to$ 无法构造非保真公式（所有变元取 $1$ 时恒为 $1$），故极小。"}, {"oj": "教材精选题", "pid": "DM-01-05", "title": "构造法证明任意命题公式与二元真值表的一一对应", "diff": "基础", "hint": "破题思路：统计 $n$ 个变元的真值指派数与极小项数，通过主析取范式唯一性确立双射。\n解答要点：\n1. $n$ 个命题变元共有 $2^n$ 种不同的真值赋值行。\n2. 每个 $n$ 变元极小项 $m_k$ 恰好只在第 $k$ 行赋值下为真，其余 $2^n - 1$ 行全为假。\n3. 任意真值表函数 $f:\\{0,1\\}^n \\to \\{0,1\\}$ 均唯一对应于取值为 $1$ 的那些极小项的析取，因此 $n$ 个变元共有 $2^{2^n}$ 个互不等值的命题公式。"}]}, {"cid": "dm-ch02", "title": "第2章 一阶谓词逻辑与量词推理（Predicate Logic & Quantifiers）", "summary": "本章在命题逻辑基础上引入个体词、谓词与全称量词 $\\forall$、存在量词 $\\exists$，极大拓展了数学与计算机规范的形式化表达能力。量词辖域内的约束变元可做改名（$\\alpha$-变换）以消除同名冲突，通过量词否定等值式 $\\neg \\forall x P(x) \\Leftrightarrow \\exists x \\neg P(x)$ 与辖域扩张律，任何谓词公式都可等价转化为量词全部前置的前束范式（Prenex Normal Form）。在一阶自然推理中，全称消去（UI）、存在消去（EI）、全称引入（UG）与存在引入（EG）构成核心规则；其中必须严守“EI 优先于 UI”与“UG 不得作用于由 EI 引入的特定常量或自由依赖变元”的限制，否则将引发类似 $\\forall x \\exists y R(x,y) \\vdash \\exists y \\forall x R(x,y)$ 的逻辑谬误。", "template_cpp": "// 前束范式 (PNF) 构造四步标准流程骨架\n// 1. 消去 -> 与 <-> (转化为 ~, /\\, \\/)\n// 2. 德摩根律与量词否定律 (~forall x P <-> exists x ~P) 将否定内移至原子谓词前\n// 3. 换名规则消除约束变元与自由变元或嵌套量词间的同名冲突\n// 4. 量词辖域扩张律将所有 Qx 移至公式最左端: (Q1 x1)(Q2 x2)...(Qk xk) M", "pitfalls": "1. 误将“所有学生都喜欢某些课程”形式化为 $\\forall x (S(x) \\to \\exists y (C(y) \\to L(x,y)))$（正确应为 $\\exists y (C(y) \\land L(x,y))$，即全称配蕴涵、存在配合取）；2. 颠倒嵌套量词顺序，混淆 $\\forall x \\exists y$ 与 $\\exists y \\forall x$；3. 在自然推理中对经由存在消去（EI）得到的特指个体常数 $c$ 违法使用全称引入（UG）。", "workbench_tags": ["一阶逻辑形式化", "前束范式", "量词辖域", "UI/EI/UG/EG规则", "嵌套量词"], "problems": [{"oj": "教材精选题", "pid": "DM-02-01", "title": "自然语言与数学定义的一阶谓词形式化（含唯一性量词）", "diff": "基础", "hint": "破题思路：严格区分“存在唯一 $\\exists! x$”的展开方式，并遵循“$\\forall$ 主联结词用 $\\to$，$\\exists$ 主联结词用 $\\land$”的黄金法则。\n解答要点：\n1. “每个实数都有唯一的加法逆元”（论域为实数集 $\\mathbb{R}$）：\n   $\\forall x \\exists y (x + y = 0 \\land \\forall z (x + z = 0 \\to z = y))$。\n2. 极限 $\\lim_{x\\to a} f(x) = L$ 的 $\\varepsilon-\\delta$ 形式化定义：\n   $\\forall \\varepsilon (\\varepsilon > 0 \\to \\exists \\delta (\\delta > 0 \\land \\forall x (0 < |x - a| < \\delta \\to |f(x) - L| < \\varepsilon)))$。\n3. “恰好有两个学生通过了考试”（$S(x)$ 表学生，$P(x)$ 表通过）：\n   $\\exists x \\exists y (S(x)\\land S(y)\\land P(x)\\land P(y)\\land x\\ne y \\land \\forall z ((S(z)\\land P(z)) \\to (z=x \\lor z=y)))$。"}, {"oj": "教材精选题", "pid": "DM-02-02", "title": "将复杂谓词公式化为前束范式（Prenex Normal Form）", "diff": "中档", "hint": "破题思路：先消去 $\\to$ 并把 $\\neg$ 推入量词内部，再对冲突约束变元换名，最后利用辖域扩张提取量词。\n解答要点：\n1. 求 $\\forall x P(x,y) \\to \\neg \\exists x Q(x,y)$ 的前束范式。\n2. 消去蕴涵：$\\neg \\forall x P(x,y) \\lor \\neg \\exists x Q(x,y)$。\n3. 量词否定内移：$\\exists x \\neg P(x,y) \\lor \\forall x \\neg Q(x,y)$。\n4. 约束变元改名避免冲突（将后者 $x$ 改为 $z$）：$\\exists x \\neg P(x,y) \\lor \\forall z \\neg Q(z,y)$。\n5. 辖域扩张移出量词：$\\exists x \\forall z (\\neg P(x,y) \\lor \\neg Q(z,y))$（注：此时 $y$ 仍为自由变元）。"}, {"oj": "教材精选题", "pid": "DM-02-03", "title": "严格使用 UI/EI/UG/EG 规则完成量词推理证明", "diff": "中档", "hint": "破题思路：对含 $\\exists$ 的前提先使用 EI 引入新常量，再对含 $\\forall$ 的前提使用 UI 代入同一常量。\n解答要点：\n1. 前提：$\\forall x (P(x) \\to Q(x))$，$\\exists x (P(x) \\land R(x))$；结论：$\\exists x (Q(x) \\land R(x))$。\n2. 由 $\\exists x (P(x) \\land R(x))$ 应用 EI，得 $P(c) \\land R(c)$（$c$ 为新个体常元）。\n3. 化简合取式得 $P(c)$ 和 $R(c)$。\n4. 对 $\\forall x (P(x) \\to Q(x))$ 应用 UI（代入常元 $c$），得 $P(c) \\to Q(c)$。\n5. 假言推理（MP）得 $Q(c)$，合取引入得 $Q(c) \\land R(c)$，最后应用 EG 得 $\\exists x (Q(x) \\land R(x))$。"}, {"oj": "教材精选题", "pid": "DM-02-04", "title": "剖析量词推理中的非法 UG 谬误并构造反例模型", "diff": "压轴", "hint": "破题思路：检查是否将依赖于存在实例的个体当作任意个体做全称概括，并给出一个有限论域反例。\n解答要点：\n1. 考察错误推导：由前提 $\\forall x \\exists y R(x,y)$，令任意个体 $a$ 用 UI 得 $\\exists y R(a,y)$，再用 EI 得 $R(a,b)$，最后错误地对 $b$ 跨过 $a$ 使用 UG 得 $\\exists y \\forall x R(x,y)$。\n2. 错因：EI 引入的 $b$ 实质上是依赖于 $a$ 的函数 $b = f(a)$（Skolem 函数），因此 $a$ 出现于 $R(a,b)$ 时已不再是自由且无依赖的任意个体，不能对 $a$ 做 UG 移到 $\\exists y$ 内侧。\n3. 反例：论域 $D = \\mathbb{Z}$，$R(x,y)$ 为“$x < y$”。显然 $\\forall x \\exists y (x < y)$ 为真，但 $\\exists y \\forall x (x < y)$（存在最大整数）为假。"}]}, {"cid": "dm-ch03", "title": "第3章 集合、二元关系与等价/偏序结构（Sets, Relations & Orderings）", "summary": "本章系统研究二元关系 $R \\subseteq A \\times A$ 的代数运算、性质判定与两类核心序结构。关系矩阵与关系图直观刻画了自反性、反自反性、对称性、反对称性与传递性；通过构造自反闭包 $r(R) = R \\cup I_A$、对称闭包 $s(R) = R \\cup R^{-1}$ 及传递闭包 $t(R) = \\bigcup_{k=1}^n R^k$（利用 $O(n^3)$ 的 Warshall 动态规划算法高效求解），可将任意关系扩充至目标性质。同时满足自反、对称与传递的关系称为等价关系，其等价类构成的商集 $A/R$ 与集合 $A$ 的划分存在双射（基数为 $n$ 的集合等价关系总数等于贝尔数 $B_n$）。同时满足自反、反对称与传递的关系称为偏序，可用哈斯图（Hasse Diagram）精简表示其覆盖关系，进而定义极小/极大元、最小/最大元、上下界以及格（Lattice）和拓扑排序。", "template_cpp": "// Warshall 算法求传递闭包 O(n^3)\n#include <bits/stdc++.h>\nusing namespace std;\nvoid warshall(vector<vector<int>>& M) {\n    int n = M.size();\n    for (int k = 0; k < n; ++k)\n        for (int i = 0; i < n; ++i)\n            if (M[i][k])\n                for (int j = 0; j < n; ++j)\n                    M[i][j] |= M[k][j];\n}", "pitfalls": "1. 误认为对称性与反对称性互为否定（例如空关系与恒等关系 $I_A$ 同时满足对称和反对称，而一般关系可两者都不满足）；2. 对任意关系先求传递闭包再求对称闭包，得到的结果可能不再具有传递性（正确顺序为先对称后传递 $ts(R)$）；3. 在哈斯图中混淆“极大元”（上方无连线元素，可不唯一）与“最大元”（大于等于所有元素，若存在则唯一）。", "workbench_tags": ["Warshall算法", "关系闭包", "等价关系与商集", "偏序与哈斯图", "拓扑排序"], "problems": [{"oj": "教材精选题", "pid": "DM-03-01", "title": "Warshall 算法逐步手算关系传递闭包", "diff": "基础", "hint": "破题思路：按中间点 $k = 1, 2, \\dots, n$ 迭代更新矩阵 $W^{(k)}$，当 $W_{ik}=1$ 时把第 $k$ 行按位或到第 $i$ 行。\n解答要点：\n1. 设 $A = \\{1,2,3,4\\}$，$R = \\{(1,2), (2,3), (3,4), (2,1)\\}$，初始矩阵 $W^{(0)}$ 非零项为 $(1,2),(2,1),(2,3),(3,4)$。\n2. $k=1$：仅第 $2$ 行第 $1$ 列为 $1$，将第 $1$ 行并入第 $2$ 行，新增 $(2,2)$。\n3. $k=2$：第 $1, 2$ 行第 $2$ 列为 $1$，将第 $2$ 行 $(2,1),(2,2),(2,3)$ 并入第 $1$ 行，新增 $(1,1), (1,3)$。\n4. $k=3$：第 $1, 2$ 行第 $3$ 列为 $1$，将第 $3$ 行 $(3,4)$ 并入第 $1, 2$ 行，新增 $(1,4), (2,4)$。\n5. $k=4$：第 $4$ 行为全零，无新增。最终传递闭包使 $\\{1,2\\}$ 互相可达且均可达 $3, 4$，$3$ 可达 $4$。"}, {"oj": "教材精选题", "pid": "DM-03-02", "title": "等价关系判定、商集构造与第二类斯特林数计数", "diff": "中档", "hint": "破题思路：逐一验证自反、对称、传递三性质；等价类数即划分块数，对应第二类斯特林数 $S(n,k)$。\n解答要点：\n1. 在 $\\mathbb{Z}$ 上定义 $x R y \\iff x^2 \\equiv y^2 \\pmod 5$。\n2. 自反性：$x^2 \\equiv x^2$ 成立；对称性：$x^2 \\equiv y^2 \\Rightarrow y^2 \\equiv x^2$；传递性：由同余传递性成立，故为等价关系。\n3. 考察模 $5$ 平方剩余：$0^2\\equiv 0$，$(\\pm 1)^2 \\equiv 1$，$(\\pm 2)^2 \\equiv 4 \\pmod 5$。因此商集 $\\mathbb{Z}/R$ 共有 $3$ 个等价类：$[0] = \\{5k\\}$，$[1] = \\{5k\\pm 1\\}$，$[2] = \\{5k\\pm 2\\}$。\n4. 拓展计数：含 $4$ 个元素的集合共可定义 $B_4 = \\sum_{k=1}^4 S(4,k) = 1 + 7 + 6 + 1 = 15$ 个不同等价关系。"}, {"oj": "教材精选题", "pid": "DM-03-03", "title": "偏序集哈斯图绘制与特殊元素及格判定", "diff": "中档", "hint": "破题思路：去掉自反与传递边，按整除/包含层级自底向上绘制覆盖边，再按定义检索极值元、上下界与最小上界/最大下界。\n解答要点：\n1. 考察偏序集 $(D_{36}, \\mid)$，其中 $D_{36} = \\{1,2,3,4,6,9,12,18,36\\}$ 为 $36$ 的正因子集合。\n2. 覆盖边（差一个素因子）：$1\\to 2, 1\\to 3$；$2\\to 4, 2\\to 6$；$3\\to 6, 3\\to 9$；$4\\to 12$；$6\\to 12, 6\\to 18$；$9\\to 18$；$12\\to 36, 18\\to 36$。\n3. 最小元为 $1$（唯一极小元），最大元为 $36$（唯一极大元）。\n4. 对子集 $B = \\{4, 6\\}$：上界为 $\\{12, 36\\}$，最小上界（上确界）$\\text{lcm}(4,6) = 12$；下界为 $\\{1, 2\\}$，最大下界（下确界）$\\gcd(4,6) = 2$。因任意两元素均有唯一 $\\text{lcm}$ 和 $\\gcd$，$(D_{36}, \\mid)$ 构成一个格（Lattice）。"}, {"oj": "教材精选题", "pid": "DM-03-04", "title": "关系闭包运算交换律的证明与反例", "diff": "压轴", "hint": "破题思路：比较 $rs(R)$ 与 $sr(R)$、$ts(R)$ 与 $st(R)$，通过元素追踪证明相等或构造 2 元集合反例。\n解答要点：\n1. 证明 $rs(R) = sr(R)$：$rs(R) = (R \\cup R^{-1}) \\cup I_A = (R \\cup I_A) \\cup (R^{-1} \\cup I_A^{-1}) = sr(R)$（因为 $I_A^{-1} = I_A$）。\n2. 证明 $st(R) \\subseteq ts(R)$ 但反之未必成立：设 $A = \\{1, 2\\}$，$R = \\{(1,2)\\}$。\n3. 先对称再传递：$s(R) = \\{(1,2),(2,1)\\}$，其传递闭包 $ts(R) = \\{(1,1),(1,2),(2,1),(2,2)\\}$。\n4. 先传递再对称：$t(R) = \\{(1,2)\\}$，再对称得 $st(R) = \\{(1,2),(2,1)\\}$，缺少 $(1,1)$ 与 $(2,2)$，不具传递性！故构造包含原关系的最小等价关系必须做 $tsr(R)$。"}, {"oj": "教材精选题", "pid": "DM-03-05", "title": "有限偏序集的拓扑排序构造全序扩展", "diff": "基础", "hint": "破题思路：反复选取当前入度为 $0$（极小元）的节点输出并删除其出边，即 Kahn 算法。\n解答要点：\n1. 设任务集合 $\\{a,b,c,d,e\\}$ 偏序依赖为 $a\\prec c, b\\prec c, c\\prec d, c\\prec e$。\n2. 初始极小元为 $a, b$，任选 $a$ 输出，删去 $a$ 后极小元仅剩 $b$；输出 $b$ 后极小元变为 $c$。\n3. 输出 $c$ 后极小元为 $d, e$，可按任意顺序输出，得到合法拓扑序列如 $(a,b,c,d,e)$ 或 $(b,a,c,e,d)$。"}]}, {"cid": "dm-ch04", "title": "第4章 函数、基数与不可数无穷（Functions, Cardinality & Countability）", "summary": "本章从映射的代数性质跃升至无穷集合的基数比较。函数 $f: A\\to B$ 存在双边逆函数的充要条件是其为双射（既单又满）；对于复合函数 $g\\circ f$，其单射性必蕴含内层 $f$ 为单射，满射性必蕴含外层 $g$ 为满射。在有限计数方面，鸽巢原理及其广义形式是存在性证明的利器。面对无穷集合，Cantor 以双射定义等势（$A\\approx B$），证明整数集 $\\mathbb{Z}$ 与有理数集 $\\mathbb{Q}$ 均为可数无穷（基数为 $\\aleph_0$），而实数区间 $(0,1)$ 与幂集 $\\mathcal{P}(\\mathbb{N})$ 不可数（基数为连续统 $\\mathfrak{c} = 2^{\\aleph_0} > \\aleph_0$）。利用 Cantor-Schröder-Bernstein 定理（若 $|A|\\le |B|$ 且 $|B|\\le |A|$，则 $|A|=|B|$），无需显式构造复杂双射即可严格判定无穷集合等势。", "template_cpp": "// Cantor-Schroder-Bernstein 定理构造思路与鸽巢原理核心不等式\n// 1. 若存在单射 f: A -> B 与 g: B -> A，则 |A| = |B|\n// 2. 广义鸽巢原理: N 个物体放入 k 个盒子，至少有一个盒子含 >= ceil(N / k) 个物体\n// 3. Cantor 对角线法: 对任意枚举 {r_1, r_2, ...}，构造 d 的第 i 位异于 r_i 的第 i 位", "pitfalls": "1. 误认为 $g\\circ f$ 是单射就一定能推出外层 $g$ 也是单射（反例：在 $f$ 值域之外 $g$ 可以碰撞）；2. 用 Cantor 对角线法构造新实数时允许出现 $9$ 或 $0$，导致无限循环小数 $0.4999\\dots = 0.5000\\dots$ 的非唯一表示漏洞（安全做法是只取数字 $2$ 和 $7$）；3. 混淆“可数集”（有限集或可数无穷集）与“可数无穷集”。", "workbench_tags": ["双射与逆函数", "加强鸽巢原理", "可数集枚举", "Cantor对角线法", "Schröder-Bernstein定理"], "problems": [{"oj": "教材精选题", "pid": "DM-04-01", "title": "复合函数单射与满射性的充分必要剖析", "diff": "基础", "hint": "破题思路：利用元素追逐法证明必要条件，并构造简单有限集合反例否定多余命题。\n解答要点：\n1. 证明若 $g\\circ f$ 为单射，则 $f$ 必为单射：任取 $a_1, a_2 \\in A$ 使 $f(a_1) = f(a_2)$，两边作用 $g$ 得 $g(f(a_1)) = g(f(a_2))$，由 $g\\circ f$ 单射性即得 $a_1 = a_2$。\n2. 反例说明 $g$ 未必单射：令 $A = \\{1\\}, B = \\{1, 2\\}, C = \\{1\\}$，$f(1) = 1$，$g(1) = g(2) = 1$，则 $g\\circ f(1)=1$ 单射，但 $g$ 非单射。\n3. 对偶结论：若 $g\\circ f$ 为满射，则 $g$ 必为满射，但 $f$ 未必满射。"}, {"oj": "教材精选题", "pid": "DM-04-02", "title": "加强鸽巢原理证明 Erdős-Szekeres 单调子序列定理", "diff": "压轴", "hint": "破题思路：为序列中每个元素 $a_k$ 赋予一对长度标签 $(i_k, d_k)$，反证若长度均不超过 $n$ 则标签总数至多 $n^2$。\n解答要点：\n1. 证明：任意 $n^2 + 1$ 个互异实数构成的序列必包含长度至少为 $n+1$ 的严格递增或严格递减子序列。\n2. 对每个位置 $k \\in \\{1, \\dots, n^2+1\\}$，记 $i_k$ 为以 $a_k$ 结尾的最长递增子序列长度，$d_k$ 为以 $a_k$ 结尾的最长递减子序列长度。\n3. 反设所有 $1 \\le i_k, d_k \\le n$，则有序对 $(i_k, d_k)$ 至多有 $n^2$ 种可能。由鸽巢原理必存在 $s < t$ 使 $(i_s, d_s) = (i_t, d_t)$。\n4. 因数互异，若 $a_s < a_t$，则 $a_t$ 可接在 $a_s$ 递增子序列后使 $i_t \\ge i_s + 1$；若 $a_s > a_t$，则 $d_t \\ge d_s + 1$，均矛盾！证毕。"}, {"oj": "教材精选题", "pid": "DM-04-03", "title": "构造法与 Schröder-Bernstein 定理证明 $(0,1)$ 与 $[0,1]$ 等势", "diff": "中档", "hint": "破题思路：方法一用希尔伯特旅馆移位构造显式双射；方法二用单射嵌入直接套用 SB 定理。\n解答要点：\n1. 显式双射构造：选取 $(0,1)$ 中的可数无穷子序列 $S = \\{1/2, 1/3, 1/4, \\dots\\}$。\n2. 定义 $f: [0,1] \\to (0,1)$ 为：\n   - $f(0) = 1/2, f(1) = 1/3$；\n   - 对 $n \\ge 2$，$f(1/n) = 1/(n+2)$；\n   - 对其余 $x \\notin \\{0, 1\\} \\cup S$，取恒等映射 $f(x) = x$。易验证 $f$ 为双射。\n3. SB 定理法：取恒等单射 $f: (0,1)\\to [0,1]$，$f(x)=x$；再取单射 $g: [0,1]\\to (0,1)$，$g(x) = \\frac{1}{2}x + \\frac{1}{4}$。由 SB 定理直接得 $|(0,1)| = |[0,1]| = \\mathfrak{c}$。"}, {"oj": "教材精选题", "pid": "DM-04-04", "title": "证明所有有限长度 01 串集合可数而无穷 01 序列集合不可数", "diff": "中档", "hint": "破题思路：有限串按长度分层可数并枚举；无穷序列用 Cantor 对角线法反证。\n解答要点：\n1. 令 $B_k$ 为长度为 $k$ 的 01 串集合，则 $|B_k| = 2^k$ 有限。全体有限串 $\\Sigma^* = \\bigcup_{k=0}^\\infty B_k$ 为可数个有限集的并，按长度递增再按字典序排列即得与 $\\mathbb{N}$ 的双射，故基数为 $\\aleph_0$。\n2. 反设无穷 01 序列集 $B^\\infty$ 可数，将其列为 $s_1, s_2, \\dots$，其中 $s_i = (b_{i,1}, b_{i,2}, \\dots)$。\n3. 构造新序列 $s^* = (1-b_{1,1}, 1-b_{2,2}, \\dots)$，其第 $k$ 位与 $s_k$ 相异，故 $s^*$ 不在列表中，矛盾，从而 $|B^\\infty| = \\mathfrak{c}$。"}]}, {"cid": "dm-ch05", "title": "第5章 初等数论、同余与密码学基础（Number Theory & Modular Arithmetic）", "summary": "本章构建离散数学中整数整除、同余算术与现代公钥密码学的理论基础。核心起点是欧几里得算法及扩展欧几里得算法（Extended Euclidean Algorithm），它不仅以 $O(\\log b)$ 复杂度求最大公因数 $\\gcd(a,b)$，还构造出贝祖等式 $sa + tb = \\gcd(a,b)$ 的整数解，进而判定线性同余方程 $ax \\equiv b \\pmod m$ 有解的充要条件为 $\\gcd(a,m)\\mid b$ 并在互素时唯一确定模逆元 $a^{-1} \\bmod m$。当模数两两互素时，中国剩余定理（CRT）保证一元线性同余方程组在模 $M = \\prod m_i$ 下存在唯一解。结合费马小定理与欧拉定理 $a^{\\varphi(n)} \\equiv 1 \\pmod n$，即可严格证明 RSA 算法（$e d \\equiv 1 \\pmod{\\varphi(pq)}$）对所有与 $n=pq$ 互素乃至不互素明文的加解密恒等性 $(M^e)^d \\equiv M \\pmod{pq}$。", "template_cpp": "#include <bits/stdc++.h>\nusing namespace std;\nusing ll = long long;\nll exgcd(ll a, ll b, ll &x, ll &y) {\n    if (b == 0) { x = 1; y = 0; return a; }\n    ll d = exgcd(b, a % b, y, x);\n    y -= (a / b) * x;\n    return d;\n}\nll mod_inv(ll a, ll m) {\n    ll x, y;\n    ll d = exgcd(a, m, x, y);\n    return d == 1 ? (x % m + m) % m : -1;\n}", "pitfalls": "1. 应用中国剩余定理（CRT）时忘记验证模数 $m_1, m_2, \\dots, m_k$ 是否两两互素；2. 使用欧拉定理降幂 $a^k \\equiv a^{k \\bmod \\varphi(n)} \\pmod n$ 时未检查 $\\gcd(a,n)=1$ 条件（若不互素且 $k \\ge \\varphi(n)$ 需用扩展欧拉定理加 $\\varphi(n)$）；3. 计算 RSA 私钥 $d$ 时误对 $n = pq$ 而非 $\\varphi(n) = (p-1)(q-1)$ 求逆元。", "workbench_tags": ["扩展欧几里得", "模逆元", "中国剩余定理", "欧拉定理", "RSA密码学"], "problems": [{"oj": "教材精选题", "pid": "DM-05-01", "title": "扩展欧几里得求模逆元与线性同余方程通解", "diff": "基础", "hint": "破题思路：先做辗转相除记录商，再回代写出贝祖等式，最后放缩并列出模 $m$ 下的所有 $\\gcd(a,m)$ 个不同余解。\n解答要点：\n1. 求解 $6x \\equiv 10 \\pmod{14}$。\n2. 计算 $d = \\gcd(6, 14) = 2$。因 $2 \\mid 10$，方程在模 $14$ 下有 $2$ 个不同余解。\n3. 两边同除以 $2$ 化为 $3x \\equiv 5 \\pmod 7$。\n4. 扩展欧几里得求 $3$ 模 $7$ 逆元：$7 = 2\\times 3 + 1 \\Rightarrow 1 = 7 - 2\\times 3$，故 $3^{-1} \\equiv -2 \\equiv 5 \\pmod 7$。\n5. 得 $x \\equiv 5\\times 5 = 25 \\equiv 4 \\pmod 7$，还原模 $14$ 下的两个解为 $x \\equiv 4, 11 \\pmod{14}$。"}, {"oj": "教材精选题", "pid": "DM-05-02", "title": "中国剩余定理（CRT）求解同余方程组", "diff": "中档", "hint": "破题思路：计算总模数 $M = \\prod m_i$，对每个 $M_i = M/m_i$ 求模 $m_i$ 逆元 $y_i$，再加权求和 $x \\equiv \\sum a_i M_i y_i \\pmod M$。\n解答要点：\n1. 求解同余方程组：$x \\equiv 2 \\pmod 3$，$x \\equiv 3 \\pmod 5$，$x \\equiv 2 \\pmod 7$。\n2. 模数 $3, 5, 7$ 两两互素，$M = 3\\times 5\\times 7 = 105$。\n3. 计算各分量：\n   - $M_1 = 35 \\equiv 2 \\pmod 3 \\Rightarrow y_1 = 2^{-1} \\equiv 2 \\pmod 3$；\n   - $M_2 = 21 \\equiv 1 \\pmod 5 \\Rightarrow y_2 = 1$；\n   - $M_3 = 15 \\equiv 1 \\pmod 7 \\Rightarrow y_3 = 1$。\n4. 合成解：$x \\equiv 2\\times 35\\times 2 + 3\\times 21\\times 1 + 2\\times 15\\times 1 = 140 + 63 + 30 = 233 \\equiv 23 \\pmod{105}$。"}, {"oj": "教材精选题", "pid": "DM-05-03", "title": "利用欧拉定理化简高次幂模运算", "diff": "中档", "hint": "破题思路：计算 $\\varphi(n)$ 并检验底数是否与 $n$ 互素，将指数对 $\\varphi(n)$ 取模后结合快速幂计算。\n解答要点：\n1. 求 $7^{2026} \\bmod 100$。\n2. 因 $\\gcd(7, 100) = 1$，且 $\\varphi(100) = 100(1 - 1/2)(1 - 1/5) = 40$。\n3. 由欧拉定理 $7^{40} \\equiv 1 \\pmod{100}$。\n4. 指数取模：$2026 = 50 \\times 40 + 26$，故 $7^{2026} \\equiv 7^{26} \\pmod{100}$。\n5. 计算小幂次：$7^2 = 49, 7^4 = 2401 \\equiv 1 \\pmod{100}$！因此 $7^{26} = (7^4)^6 \\cdot 7^2 \\equiv 1^6 \\cdot 49 = 49 \\pmod{100}$。"}, {"oj": "教材精选题", "pid": "DM-05-04", "title": "RSA 密钥生成、加密解密及非互素明文正确性证明", "diff": "压轴", "hint": "破题思路：实际演算一套 RSA 参数，并用中国剩余定理（CRT）分模 $p$ 和模 $q$ 证明即使 $\\gcd(M, n)\\ne 1$ 解密仍成立。\n解答要点：\n1. 选取 $p=5, q=11$，则 $n = 55, \\varphi(n) = 4\\times 10 = 40$。取公钥 $e = 3$（与 $40$ 互素），求得私钥 $d = 27$（因 $3\\times 27 = 81 \\equiv 1 \\pmod{40}$）。\n2. 加密明文 $M = 10$（注意 $\\gcd(10, 55) = 5 \\ne 1$）：密文 $C = 10^3 \\bmod 55 = 1000 \\bmod 55 = 10$。\n3. 正确性通证：设 $ed = 1 + k(p-1)(q-1)$。在模 $p$ 下，若 $p\\mid M$ 则 $M^{ed} \\equiv 0 \\equiv M \\pmod p$；若 $p\\nmid M$ 则由费马小定理 $M^{p-1} \\equiv 1 \\pmod p$，故 $M^{ed} = M \\cdot (M^{p-1})^{k(q-1)} \\equiv M \\pmod p$。\n4. 同理 $M^{ed} \\equiv M \\pmod q$，因 $\\gcd(p,q)=1$，由 CRT 必有 $M^{ed} \\equiv M \\pmod{pq}$。"}]}, {"cid": "dm-ch06", "title": "第6章 高级计数、容斥原理与生成函数（Counting, Inclusion-Exclusion & Generating Functions）", "summary": "本章整合组合数学中最强有力的三大分析工具：容斥原理、递推关系与生成函数。容斥原理通过交替加减交集基数精确处理带多重约束的计数问题，经典应用包括错排问题 $D_n = n!\\sum_{k=0}^n \\frac{(-1)^k}{k!}$ 与欧拉函数 $\\varphi(n)$ 的乘积公式。对于线性常系数递推方程 $a_n = c_1 a_{n-1} + \\dots + c_k a_{n-k} + f(n)$，通过特征方程求解齐次通解（$m$ 重根 $r$ 对应 $(A_0 + A_1 n + \\dots + A_{m-1}n^{m-1})r^n$）并叠加特解即可封闭求解。普通生成函数（OGF）$G(x) = \\sum a_n x^n$ 将组合计数与整数分拆转化为幂级数乘法，而指数生成函数（EGF）$\\hat{G}(x) = \\sum a_n \\frac{x^n}{n!}$ 则天然适配带标号排列计数。", "template_cpp": "// 递推与计数常用公式骨架\n// 1. Catalan 数: C_n = C(2n, n) / (n + 1), 生成函数 C(x) = (1 - sqrt(1 - 4x)) / (2x)\n// 2. 错排递推: D_n = (n - 1) * (D_{n-1} + D_{n-2}), D_0 = 1, D_1 = 0\n// 3. OGF 乘法对应序列卷积 (无标号组合), EGF 乘法对应带标号二项卷积", "pitfalls": "1. 求解非齐次递推方程时，当非齐次项 $f(n) = P(n)s^n$ 中的底数 $s$ 恰好是特征方程的 $m$ 重根时，特解忘记乘以 $n^m$ 导致待定系数方程无解；2. 在应用容斥原理求“$x_1 + x_2 + x_3 = n$ 且每项有上界限制”的整数解个数时，漏掉多条上界同时违背的交集补偿项；3. 混淆 OGF 与 EGF 的适用场景（可重组合用 OGF，可重排列用 EGF）。", "workbench_tags": ["容斥原理", "错排公式", "特征根递推", "普通生成函数", "指数生成函数", "卡特兰数"], "problems": [{"oj": "教材精选题", "pid": "DM-06-01", "title": "容斥原理求解带上界的非负整数方程解数", "diff": "基础", "hint": "破题思路：先算无上界非负整数解总数为 $\\binom{n+k-1}{k-1}$，再减去违背至少一个上界（令 $x_i' = x_i - (u_i + 1) \\ge 0$）的解集并应用容斥。\n解答要点：\n1. 求 $x_1 + x_2 + x_3 = 11$ 满足 $0\\le x_1 \\le 3, 0\\le x_2 \\le 4, 0\\le x_3 \\le 6$ 的整数解个数。\n2. 全集 $|U| = \\binom{11+3-1}{2} = \\binom{13}{2} = 78$。\n3. 设 $A_1: x_1\\ge 4$，$|A_1| = \\binom{7+2}{2} = 36$；$A_2: x_2\\ge 5$，$|A_2| = \\binom{6+2}{2} = 28$；$A_3: x_3\\ge 7$，$|A_3| = \\binom{4+2}{2} = 15$。\n4. 两两交集：$|A_1\\cap A_2| = \\binom{2+2}{2} = 6$，$|A_1\\cap A_3| = \\binom{0+2}{2} = 1$，$|A_2\\cap A_3| = 0$，三交集为 $0$。\n5. 容斥得解数：$78 - (36 + 28 + 15) + (6 + 1 + 0) - 0 = 6$。"}, {"oj": "教材精选题", "pid": "DM-06-02", "title": "二阶常系数非齐次递推方程的特征根解法", "diff": "中档", "hint": "破题思路：先解齐次特征方程（注意重根情况），再根据非齐次项与特征根的重数关系设特解形式，最后代入初始条件定常数。\n解答要点：\n1. 求解 $a_n = 4a_{n-1} - 4a_{n-2} + 2^n$，初始条件 $a_0 = 1, a_1 = 4$。\n2. 齐次特征方程 $r^2 - 4r + 4 = 0$ 有二重根 $r = 2$，故齐次通解为 $a_n^{(h)} = (c_1 + c_2 n) 2^n$。\n3. 因非齐次项 $2^n$ 的底数 $2$ 恰好为二重特征根，特解必须设为 $a_n^{(p)} = A n^2 2^n$。\n4. 代入原方程：$A n^2 2^n - 4 A(n-1)^2 2^{n-1} + 4 A(n-2)^2 2^{n-2} = 2^n$，两边约去 $2^{n-2}$ 得 $4A n^2 - 8A(n^2-2n+1) + 4A(n^2-4n+4) = 4 \\Rightarrow 8A = 4 \\Rightarrow A = \\frac{1}{2}$。\n5. 代入初值 $a_0=1 \\Rightarrow c_1=1$，$a_1=4 \\Rightarrow (1 + c_2)\\cdot 2 + \\frac{1}{2}\\cdot 2 = 4 \\Rightarrow c_2 = \\frac{1}{2}$。故通解为 $a_n = (1 + \\frac{1}{2}n + \\frac{1}{2}n^2) 2^n$。"}, {"oj": "教材精选题", "pid": "DM-06-03", "title": "普通生成函数（OGF）求带奇偶限制的组合数", "diff": "中档", "hint": "破题思路：对每个可选物品按奇偶/数量约束写出因子级数，乘积化简后通过部分分式或二项式定理提取 $[x^n]$ 系数。\n解答要点：\n1. 用红、白、蓝三种球装入袋中，红球必须取偶数个，白球至多取 $1$ 个，蓝球可取任意非负整数个。求取 $n$ 个球的方案数 $a_n$。\n2. 构造 OGF：$G(x) = (1 + x^2 + x^4 + \\dots)(1 + x)(1 + x + x^2 + \\dots)$。\n3. 闭式化简：$G(x) = \\frac{1}{1-x^2} \\cdot (1+x) \\cdot \\frac{1}{1-x} = \\frac{1}{(1-x)^2} = \\sum_{n=0}^\\infty (n+1) x^n$。\n4. 令人惊叹地，尽管限制不同，系数直接为 $a_n = n + 1$。"}, {"oj": "教材精选题", "pid": "DM-06-04", "title": "指数生成函数（EGF）求带奇偶限制的字符排列数", "diff": "压轴", "hint": "破题思路：用 $\\frac{e^x + e^{-x}}{2} = \\cosh x$ 与 $\\frac{e^x - e^{-x}}{2} = \\sinh x$ 表示偶次与奇次因子，展开后读取 $\\frac{x^n}{n!}$ 系数。\n解答要点：\n1. 求由数字 $1, 2, 3$ 组成的 $n$ 位串个数，要求 $1$ 出现偶数次，$2$ 出现奇数次，$3$ 出现次数不限。\n2. 构造 EGF：$\\hat{G}(x) = \\left(1 + \\frac{x^2}{2!} + \\dots\\right)\\left(x + \\frac{x^3}{3!} + \\dots\\right) e^x = \\frac{e^x + e^{-x}}{2} \\cdot \\frac{e^x - e^{-x}}{2} \\cdot e^x$。\n3. 化简乘积：$\\hat{G}(x) = \\frac{e^{2x} - e^{-2x}}{4} e^x = \\frac{1}{4}(e^{3x} - e^{-x})$。\n4. 展开并提取 $\\frac{x^n}{n!}$ 系数：$a_n = \\frac{3^n - (-1)^n}{4}$（对 $n\\ge 1$ 成立）。"}, {"oj": "教材精选题", "pid": "DM-06-05", "title": "卡特兰数（Catalan Number）的生成函数封闭公式推导", "diff": "压轴", "hint": "破题思路：利用二次卷积递推 $C_n = \\sum_{k=0}^{n-1} C_k C_{n-1-k}$ 建立 $G(x)$ 的二次方程，再用广义二项式定理展开。\n解答要点：\n1. 设 $C_0 = 1$ 且 $C_{n+1} = \\sum_{k=0}^n C_k C_{n-k}$，则 $G(x) = \\sum_{n=0}^\\infty C_n x^n$ 满足 $G(x) = 1 + x G(x)^2$。\n2. 解二次方程并取满足 $G(0)=1$ 的负号分支：$G(x) = \\frac{1 - \\sqrt{1 - 4x}}{2x}$。\n3. 由广义二项式定理 $(1 - 4x)^{1/2} = 1 - \\sum_{n=1}^\\infty \\frac{2}{n}\\binom{2n-2}{n-1} x^n$。\n4. 代入并除以 $2x$，读取 $[x^n]$ 系数即得 $C_n = \\frac{1}{n+1}\\binom{2n}{n}$。"}]}, {"cid": "dm-ch07", "title": "第7章 图论基础、欧拉/哈密顿图与平面图（Graph Theory, Paths & Planarity）", "summary": "本章系统梳理图论的核心结构定理。由握手定理 $\\sum_{v\\in V} \\deg(v) = 2|E|$ 出发，奇数度顶点必有偶数个；度序列的可图性可通过 Havel-Hakimi 算法递归削减判定。在遍历问题中，无向连通图存在欧拉回路的充要条件是所有顶点度数为偶数（存在欧拉通路则恰有 $0$ 或 $2$ 个奇度点）；而哈密顿回路尚无简洁充要条件，常用 Dirac 定理（$n\\ge 3$ 且 $\\delta(G) \\ge n/2$）与 Ore 定理判定充分性，或通过删除 $k$ 个顶点使连通分支数超过 $k$ 来否定存在性。针对二部图，充要条件是不含奇圈（可等价于可 $2$-着色），且 Hall 婚姻定理刻画了完美匹配的存在性。最后，连通平面图严格满足欧拉公式 $V - E + F = 2$，由此导出简单平面图边数上界 $E \\le 3V - 6$（无三角形时 $E \\le 2V - 4$），结合库拉托夫斯基（Kuratowski）定理判定 $K_5$ 与 $K_{3,3}$ 的非平面性。", "template_cpp": "// Havel-Hakimi 算法判定度序列可图性 O(n^2 log n)\n#include <bits/stdc++.h>\nusing namespace std;\nbool is_graphical(vector<int> d) {\n    while (true) {\n        sort(d.rbegin(), d.rend());\n        while (!d.empty() && d.back() == 0) d.pop_back();\n        if (d.empty()) return true;\n        int k = d[0]; d.erase(d.begin());\n        if (k > (int)d.size()) return false;\n        for (int i = 0; i < k; ++i) if (--d[i] < 0) return false;\n    }\n}", "pitfalls": "1. 对无三角形二部图如 $K_{3,3}$ 误套用一般平面图边数上界 $E \\le 3V-6$（$9 \\le 12$ 通过了！）而未用无三角形平面图上界 $E \\le 2V-4$（$9 \\le 8$ 失败）；2. 应用欧拉公式 $V-E+F=2$ 时忘记前提是图必须连通（若非连通且有 $c$ 个连通分支，则 $V-E+F=c+1$）；3. 混淆二部图可 $2$-着色性与哈密顿回路存在性（如奇数顶点数二部图必无哈密顿回路）。", "workbench_tags": ["握手定理", "欧拉回路", "哈密顿图判定", "二部图与Hall定理", "平面图欧拉公式"], "problems": [{"oj": "教材精选题", "pid": "DM-07-01", "title": "Havel-Hakimi 判定度序列可图性与连通性反例", "diff": "基础", "hint": "破题思路：降序排列，删去最大度 $d_1$ 并将其后 $d_1$ 项各减 $1$，观察是否出现负值或越界。\n解答要点：\n1. 检验序列 $S_1 = (5,4,3,3,2,2,2)$：总和 $21$ 为奇数，违反握手定理（奇度点有 $3$ 个），直接非可图。\n2. 检验序列 $S_2 = (4,4,3,3,2,2)$：\n   - 删 $4$ 后后 $4$ 项减 $1$：$(3,2,2,1,2) \\to (3,2,2,2,1)$；\n   - 删 $3$ 后后 $3$ 项减 $1$：$(1,1,1,1)$；\n   - 删 $1$ 后减 $1$：$(0,1,1) \\to (1,1,0)$；\n   - 删 $1$ 后减 $1$：$(0,0)$，可图！\n3. 进一步：若要求简单图连通，需满足边数 $|E| \\ge |V|-1$ 且无全 $0$ 孤立点。"}, {"oj": "教材精选题", "pid": "DM-07-02", "title": "利用删除顶点连通分支条件证明非哈密顿图", "diff": "中档", "hint": "破题思路：任何含哈密顿回路的图 $G$，若删除非空顶点子集 $S$，剩余连通分支数 $\\omega(G-S)$ 必满足 $\\omega(G-S) \\le |S|$。\n解答要点：\n1. 证明：在一个 $n$ 阶圈 $C_n$ 上删去 $k$ 个点，最多将其切分为 $k$ 段连通弧；由于原图 $G$ 是以 $C_n$ 为生成子图的，故 $\\omega(G-S) \\le \\omega(C_n - S) \\le |S|$。\n2. 应用：考察由两个公共顶点 $u, v$ 连接三个互不相交的 $K_3$ 分支（或标准二部图 $K_{3,4}$）构成的图。\n3. 对于二部图 $K_{3,4}$（左部 $3$ 点、右部 $4$ 点），取 $S$ 为左部全部 $3$ 个顶点，删去 $S$ 后右部 $4$ 个顶点互不相连，即 $\\omega(G - S) = 4 > |S| = 3$，故 $K_{3,4}$ 绝对不存在哈密顿回路。"}, {"oj": "教材精选题", "pid": "DM-07-03", "title": "Ore 定理与 Dirac 定理应用边界辨析", "diff": "基础", "hint": "破题思路：检查最小度是否达到 $n/2$（Dirac）或所有不相邻点对度数和是否达到 $n$（Ore），注意二者均为充分非必要条件。\n解答要点：\n1. 设简单图 $G$ 有 $n = 6$ 个顶点，最小度 $\\delta(G) = 3$。因 $3 \\ge 6/2$，满足 Dirac 定理，$G$ 必有哈密顿回路。\n2. 若将 $C_6$ 看作图：每个点度数为 $2 < 3$，且不相邻点对度数和为 $4 < 6$，既不满足 Dirac 也不满足 Ore，但 $C_6$ 本身就是哈密顿回路，这说明两个定理仅为充分条件。"}, {"oj": "教材精选题", "pid": "DM-07-04", "title": "欧拉公式证明 $K_5$ 与 $K_{3,3}$ 的非平面性", "diff": "中档", "hint": "破题思路：利用平面图每个面至少由 $3$ 条（若无三角形则 $4$ 条）边围成，结合握手面定理 $2E \\ge k F$ 与 $V-E+F=2$ 导出矛盾。\n解答要点：\n1. 对任意连通简单平面图（$V\\ge 3$），每个面边界至少含 $3$ 条边，故 $2E = \\sum \\deg(f) \\ge 3F \\Rightarrow F \\le \\frac{2}{3}E$。代入欧拉公式 $2 = V - E + F \\le V - \\frac{1}{3}E$，得 $E \\le 3V - 6$。对 $K_5$：$V=5, E=10 > 3\\times 5 - 6 = 9$，故 $K_5$ 非平面。\n2. 对不含长度为 $3$ 圈的连通简单平面图（如二部图 $K_{3,3}$），每个面至少含 $4$ 条边，故 $2E \\ge 4F \\Rightarrow F \\le \\frac{1}{2}E$。代入欧拉公式得 $E \\le 2V - 4$。对 $K_{3,3}$：$V=6, E=9 > 2\\times 6 - 4 = 8$，故 $K_{3,3}$ 非平面。"}, {"oj": "教材精选题", "pid": "DM-07-05", "title": "Hall 婚姻定理判定二部图完备匹配存在性", "diff": "压轴", "hint": "破题思路：二部图 $(X, Y)$ 存在覆盖 $X$ 的匹配当且仅当 $\\forall S \\subseteq X, |N(S)| \\ge |S|$；若所有顶点度数均为 $k\\ge 1$（$k$-正则二部图），可证明必存在完美匹配。\n解答要点：\n1. 证明 $k$-正则二部图（$k\\ge 1$）必有完美匹配：首先由 $k|X| = |E| = k|Y|$ 得 $|X| = |Y|$。\n2. 任取 $S \\subseteq X$，从 $S$ 出发的边数为 $k|S|$；这些边全部落入 $N(S)$，而 $N(S)$ 中每个点至多接收 $k$ 条边，故 $k|S| \\le k|N(S)| \\Rightarrow |N(S)| \\ge |S|$。\n3. 由 Hall 定理，$G$ 存在覆盖 $X$ 的匹配；又因 $|X|=|Y|$，该匹配即为完美匹配。"}]}, {"cid": "dm-ch08", "title": "第8章 树、最小生成树与网络流基础（Trees, Spanning Trees & Network Flows）", "summary": "本章讨论无圈连通图（树）的组合性质、编码优化与网络极值问题。树具有“无圈且 $m = n-1$”、“任意两点间存在唯一简单路径”等六大等价刻画；对于 $n$ 个带标号顶点，凯莱定理（Cayley's Formula）给出生成树总数为 $n^{n-2}$，可通过长度为 $n-2$ 的 Prüfer 序列建立双射证明。在应用层面，Huffman 编码以贪心合并最小频率节点构造带权路径长度（WPL）最小的最优前缀码树；Kruskal 与 Prim 算法基于割性质（Cut Property）以贪心策略求解带权连通图的最小生成树（MST）。进一步在有向容量网络中，Ford-Fulkerson 增广路方法与最大流最小割定理（Max-Flow Min-Cut Theorem）确立了流值上界与 $s$-$t$ 割容量的强对偶性。", "template_cpp": "// Kruskal 最小生成树与并查集 O(E log E)\n#include <bits/stdc++.h>\nusing namespace std;\nstruct Edge { int u, v, w; bool operator<(const Edge& o) const { return w < o.w; } };\nint find_p(vector<int>& p, int x) { return p[x] == x ? x : p[x] = find_p(p, p[x]); }\nlong long kruskal(int n, vector<Edge>& edges) {\n    sort(edges.begin(), edges.end());\n    vector<int> p(n + 1); iota(p.begin(), p.end(), 0);\n    long long cost = 0; int cnt = 0;\n    for (auto& e : edges) {\n        int ru = find_p(p, e.u), rv = find_p(p, e.v);\n        if (ru != rv) { p[ru] = rv; cost += e.w; if (++cnt == n - 1) break; }\n    }\n    return cost;\n}", "pitfalls": "1. Prüfer 编码长度误写成 $n-1$（正确长度严格为 $n-2$，且每个顶点在序列中出现次数等于其度数减 $1$）；2. 构造 Huffman 树时在合并频率相等的节点后未保持前缀树高度平衡，虽不改变总带权路径长 WPL，但可能改变个别码字长度；3. 在 Ford-Fulkerson 增广路径搜索中遗漏反向边（残余网络中的退流边），导致无法得到全局最大流。", "workbench_tags": ["凯莱定理与Prüfer码", "Huffman最优编码", "Kruskal最小生成树", "最大流最小割定理"], "problems": [{"oj": "教材精选题", "pid": "DM-08-01", "title": "Prüfer 编码与带标号树的双向转换（Cayley 定理）", "diff": "中档", "hint": "破题思路：树转编码每次删去标号最小的叶子并记录其唯一邻点；编码转树每次取不在当前剩余编码中的最小标号与编码首元素连边。\n解答要点：\n1. 设 $6$ 个顶点的 Prüfer 编码为 $(4, 4, 1, 5)$（长度 $n-2=4$）。\n2. 初始剩余顶点集 $V = \\{1,2,3,4,5,6\\}$：\n   - 不在 $(4,4,1,5)$ 中的最小点为 $2$，连边 $(2, 4)$，删去 $2$ 与首项 $4$；\n   - 剩余编码 $(4,1,5)$，不在其中的最小剩余点为 $3$，连边 $(3, 4)$；\n   - 剩余编码 $(1,5)$，不在其中的最小剩余点为 $4$，连边 $(4, 1)$；\n   - 剩余编码 $(5)$，不在其中的最小剩余点为 $1$，连边 $(1, 5)$；\n   - 最后剩余两顶点 $\\{5, 6\\}$，连边 $(5, 6)$。\n3. 验证度数：$1$ 出现 $1$ 次故度为 $2$，$4$ 出现 $2$ 次故度为 $3$，完全吻合。"}, {"oj": "教材精选题", "pid": "DM-08-02", "title": "Huffman 最优前缀编码树构造与平均码长计算", "diff": "基础", "hint": "破题思路：每次从优先队列中弹出两个权值最小的节点合并为新内部节点，直到只剩根节点，左右分支分别赋 $0/1$。\n解答要点：\n1. 字符集频度：$a:0.08, b:0.10, c:0.12, d:0.15, e:0.20, f:0.35$。\n2. 合并过程：\n   - 合并 $a(0.08)$ 与 $b(0.10)$ 得 $n_1(0.18)$；\n   - 合并 $c(0.12)$ 与 $d(0.15)$ 得 $n_2(0.27)$；\n   - 合并 $n_1(0.18)$ 与 $e(0.20)$ 得 $n_3(0.38)$；\n   - 合并 $n_2(0.27)$ 与 $f(0.35)$ 得 $n_4(0.62)$；\n   - 合并 $n_3(0.38)$ 与 $n_4(0.62)$ 得根 $(1.00)$。\n3. 各字符码长：$f$ 为 $1$ 位？不对，由合并树得 $f$ 深度为 $2$，$c,d,e$ 深度为 $3$？注意 $n_4$ 下含 $n_2(2层)$ 与 $f(1层)$，故 $f:2$ 位，$c,d:3$ 位，$e:2$ 位，$a,b:3$ 位！\n4. 平均码长 $L = 0.35\\times 2 + 0.20\\times 2 + (0.12+0.15+0.08+0.10)\\times 3 = 0.70 + 0.40 + 1.35 = 2.45$ 比特/符号。"}, {"oj": "教材精选题", "pid": "DM-08-03", "title": "最小生成树唯一性判定与割性质证明", "diff": "中档", "hint": "破题思路：当边权互异时 MST 唯一；若存在相等边权，检验相同权值边替换是否打破圈结构或改变总权值。\n解答要点：\n1. 证明：若连通图 $G$ 所有边权互不相同，则其最小生成树唯一。\n2. 反证：设存在两棵不同的最小生成树 $T_1 \\ne T_2$。取属于 $T_1 \\oplus T_2$（对称差）中权值最小的边 $e$，不妨设 $e \\in T_1 \\setminus T_2$。\n3. 将 $e$ 加入 $T_2$ 必形成唯一基本圈 $C$，且圈 $C$ 中至少有一条边 $e' \\in T_2 \\setminus T_1$（否则 $C\\subseteq T_1$ 矛盾）。\n4. 因边权互异且 $e$ 是对称差中最小边，必有 $w(e) < w(e')$。用 $e$ 替换 $T_2$ 中的 $e'$ 得到新生成树 $T_2' = T_2 - e' + e$，其总权严格小于 $T_2$，与 $T_2$ 最小性矛盾！"}, {"oj": "教材精选题", "pid": "DM-08-04", "title": "Ford-Fulkerson 增广与最大流最小割定理验证", "diff": "压轴", "hint": "破题思路：寻找含反向退流边的增广路直至残余网络中 $s$ 无法到达 $t$，此时残余网络从 $s$ 可达的点集 $S$ 即构成最小割 $(S, T)$。\n解答要点：\n1. 设网络顶点 $\\{s, a, b, t\\}$，有向边容量：$s\\to a(10), s\\to b(10), a\\to b(2), a\\to t(4), b\\to t(8)$? 再设 $a\\to b$ 实际是常见反向退流案例：$s\\to a(10), s\\to b(10), a\\to b(1), a\\to t(10)$ 若无退流则不需；改取经典退流例：$s\\to a(10), s\\to b(10), a\\to b(8), a\\to t(2), b\\to t(10)$，若先增广 $s\\to a\\to b\\to t$ 流 $8$，再增广 $s\\to a\\to t$ 流 $2$，此时 $s\\to b$ 尚余 $10$ 但 $b\\to t$ 仅余 $2$，增广 $s\\to b\\to t$ 流 $2$ 后总流为 $12$，看似无法继续，但其实最大流就是 $12$（因割 $S=\\{s,a,b\\}, T=\\{t\\}$ 容量 $c(a,t)+c(b,t)=2+10=12$）。\n2. 构造必须使用反向边的标准例：$s\\to a(1), s\\to b(1), a\\to b(1), a\\to t(1), b\\to t(1)$。若先误选 $s\\to a\\to b\\to t$（流 $1$），残余网络出现反向边 $b\\to a(1)$，此时可沿增广路 $s\\to b \\to a \\to t$ 流 $1$，退掉 $a\\to b$ 上的流并使总流达到 $2$。\n3. 此时最小割 $(S=\\{s\\}, T=\\{a,b,t\\})$ 容量为 $c(s,a)+c(s,b)=2$，严格等于最大流 $2$。"}]}, {"cid": "dm-ch09", "title": "第9章 代数系统、群论基础与格和布尔代数（Algebraic Structures, Groups & Boolean Algebras）", "summary": "本章揭示离散结构的抽象代数本质。在集合 $S$ 上配备二元运算 $*$，依次满足封闭性与结合律构成半群，拥有幺元 $e$ 构成独异点，再使每个元素均有逆元即构成群 $(G, *)$。子群 $H\\le G$ 借助左陪集划分 $G$，直接导出群论核心——拉格朗日定理（Lagrange's Theorem）：有限群的子群阶数 $|H|$ 必整除群阶 $|G|$，由此推知素数阶群必为循环群且无非平凡子群。通过群同态 $\\phi: G\\to G'$ 与正规子群核 $\\ker(\\phi)$，建立商群同构定理 $G/\\ker(\\phi) \\cong \\text{Im}(\\phi)$。在序代数方面，格 $(L, \\land, \\lor)$ 是偏序集的代数化等价，而有界、有补且分配的格即构成布尔代数；有限布尔代数同构于幂集代数 $(\\mathcal{P}(A), \\cap, \\cup)$，其元素个数必为 $2^n$。", "template_cpp": "// 有限循环群 (Z_n, +) 的生成元判定与子群阶数枚举\n#include <bits/stdc++.h>\nusing namespace std;\nvector<int> generators_of_Zn(int n) {\n    vector<int> gens;\n    for (int a = 0; a < n; ++a)\n        if (std::gcd(a, n) == 1) gens.push_back(a);\n    return gens; // 共有 phi(n) 个生成元\n}", "pitfalls": "1. 误以为“拉格朗日定理的逆命题”成立（即认为只要 $d \\mid |G|$ 就一定存在 $d$ 阶子群，著名反例是 $12$ 阶交错群 $A_4$ 不存在 $6$ 阶子群）；2. 检验子群时忘记验证非空性，或忽略有限群只需验证封闭性即可（无限群还需验证逆元封闭）；3. 混淆格的偏序定义（任二元有上确界与下确界）与代数定义（吸收律 $a\\land(a\\lor b)=a$ 不可遗漏）。", "workbench_tags": ["群与子群判定", "拉格朗日定理", "循环群生成元", "置换群S3", "有限布尔代数"], "problems": [{"oj": "教材精选题", "pid": "DM-09-01", "title": "检验代数系统的群公理并求模乘法群的逆元", "diff": "基础", "hint": "破题思路：逐一验证封闭性、结合律、单位元与逆元存在性；模 $n$ 乘法群 $U(n)$ 由与 $n$ 互素的剩余类组成。\n解答要点：\n1. 考察 $U(10) = \\{1, 3, 7, 9\\}$ 在模 $10$ 乘法下的群结构。\n2. 封闭性：两两相乘模 $10$ 仍与 $10$ 互素，故仍在集合内；整数乘法结合律继承；单位元为 $1$。\n3. 逆元表：$1^{-1}=1$，$3\\times 7 = 21 \\equiv 1 \\Rightarrow 3^{-1}=7, 7^{-1}=3$，$9\\times 9 = 81 \\equiv 1 \\Rightarrow 9^{-1}=9$。\n4. 计算元素阶：$|1|=1, |3|=4, |7|=4, |9|=2$，故 $U(10) \\cong (\\mathbb{Z}_4, +)$ 是循环群，生成元为 $3$ 和 $7$。"}, {"oj": "教材精选题", "pid": "DM-09-02", "title": "应用拉格朗日定理证明素数阶群必为循环群", "diff": "中档", "hint": "破题思路：任取非单位元 $a \\in G$，考察由 $a$ 生成的循环子群 $\\langle a\\rangle$ 的阶，利用 $|\\langle a\\rangle| \\mid p$ 推出必等于 $p$。\n解答要点：\n1. 设群 $G$ 的阶 $|G| = p$（$p$ 为素数）。因 $p \\ge 2$，存在非单位元 $a \\in G$（$a \\ne e$）。\n2. 考察循环子群 $H = \\langle a \\rangle = \\{a^k \\mid k\\in \\mathbb{Z}\\}$。由 $a \\ne e$ 知 $|H| \\ge 2$。\n3. 根据拉格朗日定理，$|H|$ 必须整除 $|G| = p$。\n4. 因为 $p$ 是素数且 $|H| > 1$，只能有 $|H| = p = |G|$，从而 $G = \\langle a \\rangle$，即 $G$ 必为循环群（且每个非单位元都是生成元）。"}, {"oj": "教材精选题", "pid": "DM-09-03", "title": "对称群 $S_3$ 的所有子群与左陪集分解", "diff": "中档", "hint": "破题思路：先列出 $S_3$ 的 $6$ 个置换元素及阶数，再按阶数 $1, 2, 3, 6$ 枚举全部子群并检验正规性。\n解答要点：\n1. $S_3 = \\{e, (12), (13), (23), (123), (132)\\}$，阶为 $6$。\n2. 全部 $6$ 个子群：\n   - $1$ 阶：$\\{e\\}$；\n   - $2$ 阶：$H_1 = \\{e,(12)\\}, H_2 = \\{e,(13)\\}, H_3 = \\{e,(23)\\}$；\n   - $3$ 阶：$A_3 = \\{e, (123), (132)\\}$；\n   - $6$ 阶：$S_3$。\n3. 对 $H_1$ 求左陪集：$e H_1 = \\{e, (12)\\}$，$(123)H_1 = \\{(123), (13)\\}$，$(132)H_1 = \\{(132), (23)\\}$；而右陪集 $H_1 (123) = \\{(123), (23)\\} \\ne (123)H_1$，故 $H_1$ 非正规子群，而指数为 $2$ 的 $A_3$ 必为正规子群。"}, {"oj": "教材精选题", "pid": "DM-09-04", "title": "有限布尔代数的原子表示定理与整除布尔格判定", "diff": "压轴", "hint": "破题思路：有限布尔代数必同构于其原子集合的幂集代数；检验正因子整除格 $(D_n, \\mid)$ 是否为布尔代数只需检验 $n$ 是否无平方因子。\n解答要点：\n1. 考察 $(D_{30}, \\gcd, \\text{lcm}, \\overline{x}=30/x, 1, 30)$，其中 $D_{30} = \\{1,2,3,5,6,10,15,30\\}$。\n2. 因 $30 = 2\\times 3\\times 5$ 无平方因子，每个元素均有唯一补元 $\\overline{x} = 30/x$（如 $\\gcd(6,5)=1, \\text{lcm}(6,5)=30$），且 $\\gcd$ 与 $\\text{lcm}$ 满足分配律，故 $(D_{30}, \\mid)$ 是布尔代数。\n3. 它的原子（覆盖最小元 $1$ 的元素）为素因子 $\\{2, 3, 5\\}$，共有 $3$ 个原子，恰好同构于幂集布尔代数 $(\\mathcal{P}(\\{2,3,5\\}), \\cap, \\cup)$，基数为 $2^3 = 8$。\n4. 反例：$D_{12}$ 因含平方因子 $2^2$，元素 $2$ 无补元（$12/2=6$ 但 $\\gcd(2,6)=2\\ne 1$），故不是布尔代数。"}]}]}, {"id": "gh_bupt_dm", "name": "🎓 北邮 CS 学长攻略（离散数学上/下）", "author": "faranten/bupt-cs-gallery & Yokumii · GitHub", "level": "英文考试避坑", "repo_url": "https://github.com/faranten/bupt-cs-gallery", "chapters": [{"cid": "BUPT-DM-01", "title": "北邮离散数学（上/下）英文考试与教材精刷指南", "summary": "注意：北邮离散数学（上）与（下）通常为英文试卷！《离散数学（上）》选用 Rosen《Discrete Mathematics and Its Applications》，强烈建议直接结合英文术语刷透课后题，收获感极强；《离散数学（下）》（图论与代数结构）难度显著高于离散（上），会补充《Discrete Mathematical Structures》中的内容，同样建议做完课后题并对照英文题干。", "template_cpp": "高频英文术语对照：Propositional Logic / Equivalence Relation / Partial Order / Hasse Diagram / Bipartite Graph / Planar Graph / Isomorphism / Homomorphism.", "pitfalls": "考前没背英文专业词汇导致读不懂证明题题意；混淆自反/反自反、对称/反对称、偏序与全序。", "workbench_tags": ["北邮考情", "英文考试"], "problems": []}]}];
window.__WB_CHEATSHEET__ = {"title": "离散数学考前1页纸速查卡", "sections": [{"heading": "一、命题逻辑与等值演算", "items": [{"name": "蕴涵与等价基本变换", "formula": "$P\\to Q \\equiv \\neg P \\lor Q$；$P\\leftrightarrow Q \\equiv (P\\to Q)\\land (Q\\to P)$", "note": "逆否命题等价：$P\\to Q \\equiv \\neg Q \\to \\neg P$；仅当 $P=1, Q=0$ 时 $P\\to Q$ 为假。"}, {"name": "德摩根律与分配律", "formula": "$\\neg(P\\land Q)\\equiv \\neg P\\lor\\neg Q$；$P\\lor(Q\\land R)\\equiv (P\\lor Q)\\land(P\\lor R)$", "note": "析取对合取也有分配律（与普通算术不同），吸收律 $P\\lor(P\\land Q)\\equiv P$。"}, {"name": "主析取/主合取范式", "formula": "极小项 $m_i$ 对应成真赋值，极大项 $M_i$ 对应成假赋值", "note": "主析取范式下标与主合取范式下标互补（全集 $0\\sim 2^n-1$）；重言式无主合取范式。"}, {"name": "联结词完备集", "formula": "$\\{\\neg, \\land\\},\\ \\{\\neg, \\lor\\},\\ \\{\\uparrow\\},\\ \\{\\downarrow\\}$ 均功能完备", "note": "仅含 $\\{\\land, \\lor, \\to\\}$ 不完备（保真性：全 $1$ 赋值结果必为 $1$，无法表出 $\\neg P$）。"}]}, {"heading": "二、谓词逻辑与推理规则", "items": [{"name": "量词否定与分配律", "formula": "$\\neg\\forall x P(x)\\equiv\\exists x\\neg P(x)$；$\\forall x(P\\land Q)\\equiv \\forall x P \\land \\forall x Q$", "note": "注意：$\\forall x(P\\lor Q) \\not\\equiv \\forall x P \\lor \\forall x Q$；$\\exists x(P\\land Q) \\not\\equiv \\exists x P \\land \\exists x Q$。"}, {"name": "自然语言谓词符号化规则", "formula": "“所有 A 都是 B”：$\\forall x(A(x)\\to B(x))$；“有的 A 是 B”：$\\exists x(A(x)\\land B(x))$", "note": "全称量词搭蕴涵 $\\to$，存在量词搭合取 $\\land$，切勿混搭！"}, {"name": "量词消去与引入限制", "formula": "$\\forall$ 消去（UI）可任意换元；$\\exists$ 消去（EI）必须引入新个体常元 $c$", "note": "存在推广（EG）和全称推广（UG）时注意自由变元不能受限于之前 EI 引出的常元。"}, {"name": "前束范式", "formula": "所有量词全部移至公式最前端且辖域延伸至整个母式", "note": "移位前先对约束变元改名，避免同名冲突导致辖域改变。"}]}, {"heading": "三、集合、二元关系与闭包", "items": [{"name": "幂集与笛卡尔积基数", "formula": "$|\\mathcal{P}(A)| = 2^{|A|}$；$|A \\times B| = |A|\\cdot |B|$", "note": "$A \\oplus B = (A\\setminus B)\\cup(B\\setminus A)$ 满足结合律与交换律。"}, {"name": "关系的五种基本性质", "formula": "自反（对角线全 $1$）、反自反（全 $0$）、对称（$M=M^T$）、反对称、传递", "note": "对称与反对称不是非此即彼：空关系与恒等关系既对称又反对称！"}, {"name": "三种闭包求解", "formula": "$r(R)=R\\cup I_A$；$s(R)=R\\cup R^{-1}$；$t(R)=\\bigcup_{k=1}^n R^k$", "note": "求传递闭包常用 Warshall 算法 $O(n^3)$；注意先求对称闭包再求传递闭包与反序结果不同。"}, {"name": "复合关系与逆关系", "formula": "$(R\\circ S)^{-1} = S^{-1}\\circ R^{-1}$", "note": "复合顺序（右复合 vs 左复合）务必看清教材约定。"}]}, {"heading": "四、等价关系、偏序与格", "items": [{"name": "等价关系与集合划分", "formula": "等价关系（自反、对称、传递）与集合划分一一对应", "note": "$n$ 元集合上的等价关系个数等于第 $n$ 个贝尔数 $B_n$（$B_3=5, B_4=15$）。"}, {"name": "偏序关系与哈斯（Hasse）图", "formula": "偏序（自反、反对称、传递）；哈斯图省去自环、传递边与向上的箭头", "note": "区分极大元/极小元（局部无更大/更小）与最大元/最小元（全局唯一，可不存在）。"}, {"name": "上确界（LUB）与下确界（GLB）", "formula": "任意两元素都有上确界 $a\\lor b$ 和下确界 $a\\land b$ 的偏序集称为格（Lattice）", "note": "有限格必有界（有最大元 $1$ 和最小元 $0$）；分配格不含钻石格 $M_3$ 与五角格 $N_5$。"}, {"name": "布尔代数（有补分配格）", "formula": "有限布尔代数基数必为 $2^n$，同构于 $n$ 元集幂集代数 $\\mathcal{P}(S)$", "note": "如整除格 $D_n$ 为布尔代数当且仅当 $n$ 无平方因子。"}]}, {"heading": "五、组合计数与递推关系", "items": [{"name": "隔板法与不定方程非负整数解", "formula": "$x_1+\\dots+x_k = n$ 正整数解 $\\binom{n-1}{k-1}$；非负整数解 $\\binom{n+k-1}{k-1}$", "note": "若限制 $x_i \\ge c_i$，先令 $y_i = x_i - c_i \\ge 0$ 转化。"}, {"name": "圆排列与错位排列", "formula": "圆排列 $Q_n = (n-1)!$；错排 $D_n = n!\\sum_{k=0}^n \\frac{(-1)^k}{k!}$", "note": "错排递推 $D_n = (n-1)(D_{n-1}+D_{n-2})$，$D_1=0, D_2=1, D_3=2, D_4=9, D_5=44$。"}, {"name": "容斥原理（Inclusion-Exclusion）", "formula": "$|\\bigcup_{i=1}^n A_i| = \\sum |A_i| - \\sum |A_i\\cap A_j| + \\dots + (-1)^{n-1}|\\bigcap A_i|$", "note": "常用于求解有限制条件的满射个数或整数整除计数。"}, {"name": "常系数线性递推（特征根法）", "formula": "特征方程有 $k$ 重根 $r$ 时，通解贡献 $(c_0+c_1 n+\\dots+c_{k-1}n^{k-1})r^n$", "note": "非齐次项为 $P(n)a^n$ 时，特解需乘 $n^m$（$m$ 为 $a$ 作为特征根的重数）。"}]}, {"heading": "六、图论与平面图", "items": [{"name": "握手定理与树的等价性质", "formula": "$\\sum_{v\\in V} \\deg(v) = 2|E|$；树满足 $|E|=|V|-1$ 且无环连通", "note": "度数为奇数的顶点必有偶数个；$n$ 阶树至少有 $2$ 片树叶（$n\\ge 2$）。"}, {"name": "欧拉图与哈密顿图判定", "formula": "欧拉回路 $\\iff$ 连通且无奇度点；半欧拉图 $\\iff$ 恰有 $0$ 或 $2$ 个奇度点", "note": "哈密顿充分条件（Dirac）：$n\\ge 3$ 且任意点 $\\deg(v)\\ge n/2$。"}, {"name": "平面图欧拉公式", "formula": "连通平面图 $V - E + F = 2$；简单平面图 $E \\le 3V - 6$（无三角形则 $E \\le 2V - 4$）", "note": "库拉托夫斯基定理：图是平面图 $\\iff$ 不含同胚于 $K_5$ 或 $K_{3,3}$ 的子图。"}, {"name": "图着色与四色定理", "formula": "二分图 $\\iff$ 无奇圈 $\\iff \\chi(G)\\le 2$；平面图必 $4$-可着色", "note": "边着色 Vizing 定理：简单图 $\\Delta(G) \\le \\chi'(G) \\le \\Delta(G)+1$。"}]}, {"heading": "七、离散数学高频易错陷阱", "items": [{"name": "传递性空真（Vacuous Truth）陷阱", "formula": "若关系 $R$ 中不存在 $(a,b),(b,c)\\in R$ 的链，则 $R$ 自动满足传递性", "note": "如空关系 $\\emptyset$ 与仅含 $(1,2)$ 的单元素关系均满足传递性！"}, {"name": "有向图强/单向/弱连通混淆", "formula": "强连通（任意两点双向可达）$\\implies$ 单向连通 $\\implies$ 弱连通", "note": "判强连通可找经过所有点至少一次的有向闭通路。"}, {"name": "项链（手链）与圆排列对称性混淆", "formula": "圆排列只除旋转对称 $(n-1)!$；手链可翻转再除以 $2$（$n\\ge 3$）", "note": "若珠子有重复颜色，不可直接除以 $n$，必须用 Burnside 引理或 Pólya 定理。"}, {"name": "偏序极大元与上界区别", "formula": "极大元属于子集本身，而上界属于整个偏序集（可不在子集中）", "note": "子集若有最大元则唯一且必为唯一极大元；无最大元时可能有多个极大元。"}]}]};
